import pyotp
import pytest

import app.auth as auth
from app.auth import AuthError, get_session, login
from app.config import USERS


def otp_for(username: str) -> str:
    return pyotp.TOTP(USERS[username]["otp_secret"]).now()


def test_login_correcto_abre_sesion():
    s = login("alice", "alice-pass", otp_for("alice"))
    assert s.username == "alice"
    assert get_session(s.token) == s


def test_login_incorrecto():
    with pytest.raises(AuthError):
        login("alice", "mal", otp_for("alice"))
    with pytest.raises(AuthError):
        login("nadie", "alice-pass", otp_for("alice"))


def test_login_sin_otp_falla():
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "")


def test_login_otp_incorrecto_falla():
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "000000")


def test_login_requiere_argumento_otp():
    with pytest.raises(TypeError):
        login("alice", "alice-pass")


def test_verificar_otp_sustituible(monkeypatch):
    monkeypatch.setattr(auth, "verificar_otp", lambda username, code: True)
    s = login("alice", "alice-pass", "cualquier-cosa")
    assert s.username == "alice"


def test_endpoint_login(client):
    assert client.post(
        "/login",
        json={"username": "bob", "password": "bob-pass", "otp": otp_for("bob")},
    ).status_code == 200
    assert client.post(
        "/login", json={"username": "bob", "password": "x", "otp": otp_for("bob")}
    ).status_code == 401
    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass", "otp": "000000"}
    ).status_code == 401
    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass"}
    ).status_code == 401


def test_otp_header_existe_y_es_dependencia():
    assert callable(auth.otp_header)
    assert "X-OTP" in (auth.otp_header.__doc__ or "")

